// SPDX-License-Identifier: MIT
//
// Pipeline: check the bundled assets, unpack the ghost image, draw one
// standalone document variant, and write out a repeatable RGBA PNG.
// Inputs: this file plus an optional neighbouring POST.json. Anything the
// program creates goes into the output folder chosen at launch.
// The layout pass refuses characters it cannot draw, text that spills
// past its box, and text boxes that collide. Wrapping breaks only between
// words; glyphs are never squeezed to fit.

import * as fs from "node:fs";
import * as path from "node:path";
import { fileURLToPath } from "node:url";
import * as zlib from "node:zlib";

const GHOST_B64 = "";
const FONT_HEX = "";

const WIDTH = 2 ** 10;
const HEIGHT = WIDTH;
const MARGIN = 0x50;
const CONTENT_WIDTH = WIDTH - 2 * MARGIN;
const CELL_WIDTH = 0x18;
const CELL_HEIGHT = 0x14;
const LINE_HEIGHT = CELL_HEIGHT + 4;
const GLYPH_BYTES = (CELL_WIDTH * CELL_HEIGHT) >> 3;
const FONT_BYTES = GLYPH_BYTES * 95;

const SCRIPT_DIR = path.dirname(fileURLToPath(import.meta.url));

type Color = readonly [red: number, green: number, blue: number, alpha: number];
type Point = readonly [x: number, y: number];
type TextAlign = "center" | "right" | "left";
type Variant = 6 | 5 | 4 | 3 | 2 | 1;

interface Rect {
  x: number;
  y: number;
  width: number;
  height: number;
}

interface DecodedImage {
  width: number;
  height: number;
  pixels: Uint8Array;
}

interface Options {
  variant: Variant;
  outdir: string | undefined;
  help: boolean;
}

const BLACK: Color = [0x14, 0x14, 0x12, 0xff];
const CHARCOAL: Color = [0x25, 0x2b, 0x2e, 0xff];
const RED: Color = [0xa4, 0x2a, 0x24, 0xff];
const WHITE: Color = [0xff, 0xff, 0xff, 0xff];
const IVORY: Color = [0xf8, 0xf1, 0xe1, 0xff];
const IVORY_CARD: Color = [0xf1, 0xe8, 0xd3, 0xff];
const UTILITY_PAPER: Color = [0xf7, 0xf8, 0xf6, 0xff];
const UTILITY_LINE: Color = [0xc7, 0xcd, 0xcc, 0xff];
const AVATAR_BACKGROUND: Color = [0xe8, 0xec, 0xea, 0xff];
const CYAN: Color = [0x00, 0xcd, 0xeb, 0xff];
const EMPTY_PROGRESS: Color = [0x1b, 0x24, 0x2b, 0xff];

const PNG_SIGNATURE = Buffer.from([
  0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a,
]);

const CRC_TABLE = (() => {
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let value = n;
    for (let bit = 0; bit < 8; bit++) {
      value = (value & 1) !== 0
        ? 0xedb88320 ^ (value >>> 1)
        : value >>> 1;
    }
    table[n] = value >>> 0;
  }
  return table;
})();

// CRC-32 (reflected, polynomial 0xedb88320) over a byte buffer. The table
// above is built once at load time; this loop only walks it.
function checksum32(input: Uint8Array): number {
  let running = 0xffffffff;
  for (const byte of input) {
    const slot = (running ^ byte) & 0xff;
    running = CRC_TABLE[slot] ^ (running >>> 8);
  }
  return (running ^ 0xffffffff) >>> 0;
}

// One PNG chunk: 4-byte big-endian length, 4-byte ASCII type, payload, then
// a 4-byte CRC-32 over the type and payload bytes.
function frameChunk(kind: string, payload: Uint8Array): Buffer {
  const head = 8; // length field + type field
  const tail = 4; // CRC field
  const frame = Buffer.alloc(payload.length + head + tail);
  frame.writeUInt32BE(payload.length, 0);
  frame.write(kind, 4, 4, "ascii");
  frame.set(payload, head);
  const digest = checksum32(frame.subarray(4, head + payload.length));
  frame.writeUInt32BE(digest, head + payload.length);
  return frame;
}

// IHDR for a fixed 1024x1024 RGBA8 image: bit depth 8, colour type 6
// (truecolour with alpha), no compression/filter/interlace tricks.
function headerBytes(): Buffer {
  const header = Buffer.alloc(13);
  header.writeUInt32BE(WIDTH, 0);
  header.writeUInt32BE(HEIGHT, 4);
  header[8] = 8;
  header[9] = 6;
  header[10] = 0;
  header[11] = 0;
  header[12] = 0;
  return header;
}

// Prefix every row with filter byte 0 (no filtering) and copy the pixels.
function scanlineBytes(pixels: Uint8Array): Buffer {
  const rowBytes = WIDTH * 4;
  const packed = Buffer.alloc((rowBytes + 1) * HEIGHT);
  for (let row = 0; row < HEIGHT; row++) {
    const start = row * (rowBytes + 1);
    packed[start] = 0;
    packed.set(pixels.subarray(row * rowBytes, (row + 1) * rowBytes), start + 1);
  }
  return packed;
}

function encodePNG(pixels: Uint8Array): Buffer {
  if (pixels.length !== WIDTH * HEIGHT * 4) {
    throw new Error("The canvas must contain exactly 1024x1024 RGBA pixels.");
  }
  const compressed = zlib.deflateSync(scanlineBytes(pixels), { level: 9 });
  return Buffer.concat([
    PNG_SIGNATURE,
    frameChunk("IHDR", headerBytes()),
    frameChunk("IDAT", compressed),
    frameChunk("IEND", Buffer.alloc(0)),
  ]);
}

// Paeth predictor: guess a + b - c, then return whichever of the three
// neighbours (left, above, upper-left) is closest to that guess. Ties break
// toward left, then above — the order the PNG spec pins down.
function paeth(a: number, b: number, c: number): number {
  const estimate = a + b - c;
  const gapLeft = Math.abs(estimate - a);
  const gapAbove = Math.abs(estimate - b);
  const gapCorner = Math.abs(estimate - c);

  if (gapLeft <= gapAbove && gapLeft <= gapCorner) return a;
  if (gapAbove <= gapCorner) return b;
  return c;
}

// One chunk of the ghost PNG: its four-letter kind, its payload bytes,
// where the payload ends, and where the next chunk starts.
type GhostChunk = {
  kind: string;
  payload: Buffer;
  payloadEnd: number;
  nextCursor: number;
};

// Read the chunk header at cursor: a 4-byte big-endian length, a 4-byte
// ASCII kind, the payload, then a 4-byte CRC. Length and kind are checked
// here; the CRC is verified by the caller, which knows the boundaries.
function readGhostChunk(png: Buffer, cursor: number): GhostChunk {
  const payloadLength = png.readUInt32BE(cursor);
  if (payloadLength > png.length - cursor - 12) {
    throw new Error("The ghost PNG contains a truncated chunk.");
  }

  const kind = png.toString("ascii", cursor + 4, cursor + 8);
  if (!/^[A-Za-z]{4}$/.test(kind)) {
    throw new Error("The ghost PNG contains an invalid chunk type.");
  }

  const payloadStart = cursor + 8;
  const payloadEnd = payloadStart + payloadLength;
  return {
    kind,
    payload: png.subarray(payloadStart, payloadEnd),
    payloadEnd,
    nextCursor: payloadEnd + 4,
  };
}

// The stored CRC covers the kind bytes plus the payload. Recompute it and
// compare against the four bytes stored right after the payload.
function checkGhostChunkCrc(png: Buffer, cursor: number, chunk: GhostChunk): void {
  const recomputed = checksum32(png.subarray(cursor + 4, chunk.payloadEnd));
  const stored = png.readUInt32BE(chunk.payloadEnd);
  if (recomputed !== stored) {
    throw new Error(`The ghost PNG has an invalid ${chunk.kind} CRC.`);
  }
}

// IHDR must describe exactly the sprite this program embeds: 256x256,
// 8-bit, colour type 6 (truecolour with alpha), no compression, filter,
// or interlace tricks.
function readGhostDimensions(payload: Buffer): { width: number; height: number } {
  const width = payload.readUInt32BE(0);
  const height = payload.readUInt32BE(4);
  const matchesSpriteFormat =
    width === 256 &&
    height === 256 &&
    payload[8] === 8 &&
    payload[9] === 6 &&
    payload[10] === 0 &&
    payload[11] === 0 &&
    payload[12] === 0;
  if (!matchesSpriteFormat) {
    throw new Error(
      "The ghost must be a 256x256, 8-bit RGBA, non-interlaced PNG.",
    );
  }
  return { width, height };
}

// Reverse one row's PNG filter. Filter 0 leaves the byte alone; 1 takes
// the pixel to the left, 2 the pixel above, 3 their average, 4 the Paeth
// predictor over left, above, and upper-left.
function unfilterByte(
  filterKind: number,
  west: number,
  north: number,
  northWest: number,
): number {
  switch (filterKind) {
    case 0:
      return 0;
    case 1:
      return west;
    case 2:
      return north;
    case 3:
      return Math.floor((west + north) / 2);
    default:
      return paeth(west, north, northWest);
  }
}

// Undo the per-row filtering of the inflated scanlines. Each row starts
// with a filter byte, then one byte per channel, each stored as a delta
// against the predictor from its neighbours.
function unfilterGhostRows(
  filtered: Buffer,
  width: number,
  height: number,
): Uint8Array {
  const channels = 4;
  const rowBytes = width * channels;
  const pixels = new Uint8Array(width * height * channels);
  let readPos = 0;

  for (let row = 0; row < height; row++) {
    const filterKind = filtered[readPos++];
    if (filterKind > 4) {
      throw new Error(`Unsupported ghost PNG filter: ${filterKind}.`);
    }

    const rowStart = row * rowBytes;
    for (let col = 0; col < rowBytes; col++) {
      const west = col >= channels ? pixels[rowStart + col - channels] : 0;
      const north = row > 0 ? pixels[rowStart + col - rowBytes] : 0;
      const northWest =
        row > 0 && col >= channels
          ? pixels[rowStart + col - rowBytes - channels]
          : 0;
      const predictor = unfilterByte(filterKind, west, north, northWest);
      pixels[rowStart + col] = (filtered[readPos++] + predictor) & 0xff;
    }
  }

  return pixels;
}

function decodeGhostPNG(png: Buffer): DecodedImage {
  if (
    png.length < 8 ||
    !png.subarray(0, PNG_SIGNATURE.length).equals(PNG_SIGNATURE)
  ) {
    throw new Error("GHOST_B64 does not contain a PNG.");
  }

  let cursor = PNG_SIGNATURE.length;
  let width = 0;
  let height = 0;
  let headerSeen = false;
  let endSeen = false;
  let dataSeen = false;
  let dataClosed = false;
  const idatChunks: Buffer[] = [];

  chunkLoop: while (cursor + 12 <= png.length) {
    const chunk = readGhostChunk(png, cursor);
    checkGhostChunkCrc(png, cursor, chunk);

    if (!headerSeen && chunk.kind !== "IHDR") {
      throw new Error("The first ghost PNG chunk must be IHDR.");
    }

    switch (chunk.kind) {
      case "IHDR": {
        if (headerSeen || cursor !== 8 || chunk.payload.length !== 13) {
          throw new Error("The ghost PNG has an invalid IHDR.");
        }
        const dims = readGhostDimensions(chunk.payload);
        width = dims.width;
        height = dims.height;
        headerSeen = true;
        break;
      }
      case "IDAT": {
        if (dataClosed) {
          throw new Error("The ghost PNG IDAT chunks must be consecutive.");
        }
        dataSeen = true;
        idatChunks.push(chunk.payload);
        break;
      }
      case "IEND": {
        if (chunk.payload.length !== 0 || !dataSeen) {
          throw new Error("The ghost PNG has an invalid IEND.");
        }
        endSeen = true;
        cursor = chunk.nextCursor;
        break chunkLoop;
      }
      default: {
        if (dataSeen) dataClosed = true;

        // PLTE is optional in an RGBA PNG and does not affect RGBA decoding.
        const isCritical = (chunk.kind.charCodeAt(0) & 0x20) === 0;
        if (isCritical && chunk.kind !== "PLTE") {
          throw new Error(`Unsupported critical ghost PNG chunk: ${chunk.kind}.`);
        }
        break;
      }
    }

    cursor = chunk.nextCursor;
  }

  if (!headerSeen || !dataSeen || !endSeen || cursor !== png.length) {
    throw new Error("The ghost PNG is incomplete or has trailing data.");
  }

  const channels = 4;
  const rowBytes = width * channels;
  const expectedBytes = height * (rowBytes + 1);
  const scanlines = zlib.inflateSync(Buffer.concat(idatChunks), {
    maxOutputLength: expectedBytes,
  });

  if (scanlines.length !== expectedBytes) {
    throw new Error("The ghost PNG has an unexpected decompressed length.");
  }

  const pixels = unfilterGhostRows(scanlines, width, height);
  return { width, height, pixels };
}

function decodeFont(): Uint8Array {
  const expectedHexLength = FONT_BYTES * 2;
  const isHexOnly = /^[0-9a-fA-F]+$/.test(FONT_HEX);
  if (FONT_HEX.length !== expectedHexLength || !isHexOnly) {
    throw new Error(
      "Replace  with exactly 11,400 hexadecimal characters " +
      "for the 95 printable ASCII glyphs.",
    );
  }

  return Buffer.from(FONT_HEX, "hex");
}

function decodeGhost(): DecodedImage {
  const hasBytes = GHOST_B64.length > 0;
  const isPadded = GHOST_B64.length % 4 === 0;
  const isBase64Alphabet = /^[A-Za-z0-9+/]+={0,2}$/.test(GHOST_B64);
  if (!hasBytes || !isPadded || !isBase64Alphabet) {
    throw new Error(
      "Replace  with the base64-encoded 256x256 RGBA ghost PNG.",
    );
  }

  return decodeGhostPNG(Buffer.from(GHOST_B64, "base64"));
}

// Normalise a label to the glyphs the bitmap font actually carries.
// Dashes collapse to a hyphen, the middle dot to a pipe, the arrow to a
// two-character ASCII arrow, and curly quotes to a straight apostrophe.
// Anything still outside printable ASCII is rejected — the font has no
// glyph for it, so failing here is better than rendering a blank.
function normalizeText(raw: string): string {
  const ascii = raw
    .replace(/[\u2013\u2014]/g, "-")
    .replace(/\u00b7/g, "|")
    .replace(/\u2192/g, "->")
    .replace(/[\u2018\u2019]/g, "'");

  if (/[^\x20-\x7e\n]/.test(ascii)) {
    throw new Error("Text contains a character outside the embedded ASCII font.");
  }

  return ascii;
}

// Greedy word wrap over newline-separated paragraphs: pack words into
// lines no longer than maxCharacters. A word longer than the limit is an
// error (it would clip), and empty paragraphs survive as empty lines.
function wrapText(text: string, maxCharacters: number): string[] {
  if (!Number.isInteger(maxCharacters) || maxCharacters < 1) {
    throw new Error("Text wrapping requires a positive character limit.");
  }

  const lines: string[] = [];

  for (const block of normalizeText(text).split("\n")) {
    if (block.length === 0) {
      lines.push("");
      continue;
    }

    const tokens = block.split(" ").filter((token) => token.length > 0);
    let current = "";

    for (const token of tokens) {
      if (token.length > maxCharacters) {
        throw new Error(`A word cannot fit without clipping: ${token}`);
      }

      const candidate = current.length === 0 ? token : `${current} ${token}`;
      if (candidate.length <= maxCharacters) {
        current = candidate;
      } else {
        lines.push(current);
        current = token;
      }
    }

    lines.push(current);
  }

  return lines;
}

// True when two axis-aligned rectangles share any area. Degenerate
// rectangles (zero or negative width/height) never overlap anything.
function rectanglesOverlap(first: Rect, second: Rect): boolean {
  return (
    first.width > 0 &&
    second.width > 0 &&
    first.height > 0 &&
    second.height > 0 &&
    first.x < second.x + second.width &&
    first.x + first.width > second.x &&
    first.y < second.y + second.height &&
    first.y + first.height > second.y
  );
}

// Guard the 80px content frame: every drawn element must sit inside it.
// Non-finite or negative sizes are rejected too. Throws with a short
// diagnostic rather than silently clipping the image.
function assertContentRect(box: Rect, what: string): void {
  if (
    !Number.isFinite(box.x) ||
    !Number.isFinite(box.y) ||
    !Number.isFinite(box.width) ||
    !Number.isFinite(box.height) ||
    box.width < 0 ||
    box.height < 0 ||
    box.x < MARGIN ||
    box.y < MARGIN ||
    box.x + box.width > WIDTH - MARGIN ||
    box.y + box.height > HEIGHT - MARGIN
  ) {
    throw new Error(`${what} exceeds the 80px content margins.`);
  }
}

class Canvas {
  readonly pixels: Uint8Array;
  private readonly font: Uint8Array;
  private readonly textAreas: Rect[];

  constructor(glyphs: Uint8Array, base: Color) {
    this.font = glyphs;
    this.pixels = new Uint8Array(WIDTH * HEIGHT * 4);
    this.textAreas = [];
    this.fillRect(0, 0, WIDTH, HEIGHT, base);
  }

  // Composite one pixel over the buffer (source-over, premultiplied math).
  private blendPixel(
    px: number,
    py: number,
    r: number,
    g: number,
    b: number,
    a: number,
  ): void {
    if (px < 0 || py < 0 || px >= WIDTH || py >= HEIGHT || a <= 0) {
      return;
    }

    const off = (py * WIDTH + px) * 4;

    if (a >= 255) {
      this.pixels[off] = Math.round(r);
      this.pixels[off + 1] = Math.round(g);
      this.pixels[off + 2] = Math.round(b);
      this.pixels[off + 3] = 255;
      return;
    }

    const srcA = a / 255;
    const dstA = this.pixels[off + 3] / 255;
    const dstPart = dstA * (1 - srcA);
    const outA = srcA + dstPart;

    if (outA <= 0) return;

    this.pixels[off] = Math.round(
      (r * srcA + this.pixels[off] * dstPart) / outA,
    );
    this.pixels[off + 1] = Math.round(
      (g * srcA + this.pixels[off + 1] * dstPart) / outA,
    );
    this.pixels[off + 2] = Math.round(
      (b * srcA + this.pixels[off + 2] * dstPart) / outA,
    );
    this.pixels[off + 3] = Math.round(outA * 255);
  }

  // Fill a rectangle, clipped to the canvas; opaque paint writes directly.
  fillRect(
    atX: number,
    atY: number,
    wide: number,
    tall: number,
    paint: Color,
  ): void {
    if (wide <= 0 || tall <= 0) return;

    const x0 = Math.max(0, Math.floor(atX));
    const y0 = Math.max(0, Math.floor(atY));
    const x1 = Math.min(WIDTH, Math.ceil(atX + wide));
    const y1 = Math.min(HEIGHT, Math.ceil(atY + tall));

    for (let row = y0; row < y1; row++) {
      for (let col = x0; col < x1; col++) {
        if (paint[3] === 255) {
          const off = (row * WIDTH + col) * 4;
          this.pixels[off] = paint[0];
          this.pixels[off + 1] = paint[1];
          this.pixels[off + 2] = paint[2];
          this.pixels[off + 3] = 255;
        } else {
          this.blendPixel(col, row, paint[0], paint[1], paint[2], paint[3]);
        }
      }
    }
  }

  horizontalLine(
    atX: number,
    atY: number,
    len: number,
    paint: Color,
    thick = 1,
  ): void {
    this.fillRect(atX, atY, len, thick, paint);
  }

  verticalLine(
    atX: number,
    atY: number,
    len: number,
    paint: Color,
    thick = 1,
  ): void {
    this.fillRect(atX, atY, thick, len, paint);
  }

  strokeRect(
    atX: number,
    atY: number,
    wide: number,
    tall: number,
    paint: Color,
    thick = 1,
  ): void {
    const edge = Math.max(1, Math.floor(thick));
    if (wide < edge * 2 || tall < edge * 2) {
      this.fillRect(atX, atY, wide, tall, paint);
      return;
    }

    this.horizontalLine(atX, atY, wide, paint, edge);
    this.horizontalLine(atX, atY + tall - edge, wide, paint, edge);
    this.verticalLine(atX, atY + edge, tall - edge * 2, paint, edge);
    this.verticalLine(atX + wide - edge, atY + edge, tall - edge * 2, paint, edge);
  }

  // Disc via horizontal scanlines, one pixel row at a time.
  filledCircle(
    cx: number,
    cy: number,
    rad: number,
    paint: Color,
  ): void {
    if (rad <= 0) return;

    const y0 = Math.max(0, Math.floor(cy - rad));
    const y1 = Math.min(HEIGHT, Math.ceil(cy + rad));

    for (let row = y0; row < y1; row++) {
      const dy = row + 0.5 - cy;
      const halfSq = rad * rad - dy * dy;
      if (halfSq < 0) continue;

      const half = Math.sqrt(halfSq);
      const x0 = Math.ceil(cx - half - 0.5);
      const x1 = Math.ceil(cx + half - 0.5);
      this.fillRect(x0, row, x1 - x0, 1, paint);
    }
  }

  // Scanline polygon fill: collect edge crossings per row, fill between pairs.
  fillPolygon(verts: readonly Point[], paint: Color): void {
    if (verts.length < 3) return;

    let minY = Infinity;
    let maxY = -Infinity;
    for (const vert of verts) {
      minY = Math.min(minY, vert[1]);
      maxY = Math.max(maxY, vert[1]);
    }

    const y0 = Math.max(0, Math.ceil(minY - 0.5));
    const y1 = Math.min(HEIGHT, Math.ceil(maxY - 0.5));

    for (let row = y0; row < y1; row++) {
      const scan = row + 0.5;
      const hits: number[] = [];

      for (let k = 0; k < verts.length; k++) {
        const p = verts[k];
        const q = verts[(k + 1) % verts.length];

        if (
          (p[1] <= scan && q[1] > scan) ||
          (q[1] <= scan && p[1] > scan)
        ) {
          hits.push(p[0] + ((scan - p[1]) * (q[0] - p[0])) / (q[1] - p[1]));
        }
      }

      hits.sort((a, b) => a - b);

      for (let k = 0; k + 1 < hits.length; k += 2) {
        const x0 = Math.ceil(hits[k] - 0.5);
        const x1 = Math.ceil(hits[k + 1] - 0.5);
        this.fillRect(x0, row, x1 - x0, 1, paint);
      }
    }
  }

  // Ten-point star, alternating outer and inner spikes.
  filledStar(
    cx: number,
    cy: number,
    rad: number,
    paint: Color,
  ): void {
    const verts: Point[] = [];
    const inner = rad * 0.3819660112501051;

    for (let k = 0; k < 10; k++) {
      const ang = -Math.PI / 2 + (k * Math.PI) / 5;
      const spike = k % 2 === 0 ? rad : inner;
      verts.push([
        cx + Math.cos(ang) * spike,
        cy + Math.sin(ang) * spike,
      ]);
    }

    this.fillPolygon(verts, paint);
  }

  // Bar with a border, an empty track, and a fractional fill (last column blends).
  progressBar(
    atX: number,
    atY: number,
    wide: number,
    tall: number,
    frac: number,
    fill: Color,
    empty: Color,
    frame: Color,
    edge = 2,
  ): void {
    if (
      !Number.isFinite(frac) ||
      frac < 0 ||
      frac > 1 ||
      ![atX, atY, wide, tall, edge].every(Number.isInteger) ||
      edge < 1 ||
      wide <= edge * 2 ||
      tall <= edge * 2
    ) {
      throw new Error("Invalid progress bar geometry or fraction.");
    }

    assertContentRect({ x: atX, y: atY, width: wide, height: tall }, "Progress bar");

    this.fillRect(atX, atY, wide, tall, frame);

    const ix = atX + edge;
    const iy = atY + edge;
    const iw = wide - edge * 2;
    const ih = tall - edge * 2;

    this.fillRect(ix, iy, iw, ih, empty);

    // Fractional coverage preserves exactly 99%, rather than rounding the
    // fill to a different percentage. The remaining 8.6px at this layout
    // becomes approximately 4px at a 480px preview.
    const fillW = iw * frac;
    const fullCols = Math.floor(fillW);
    const partCol = fillW - fullCols;

    this.fillRect(ix, iy, fullCols, ih, fill);

    if (partCol > 0 && fullCols < iw) {
      for (let row = iy; row < iy + ih; row++) {
        this.blendPixel(
          ix + fullCols,
          row,
          fill[0],
          fill[1],
          fill[2],
          fill[3] * partCol,
        );
      }
    }
  }

  // Block text from the built-in bitmap font; every line is overlap-checked.
  drawText(
    copy: string | readonly string[],
    atX: number,
    atY: number,
    size: number,
    paint: Color,
    anchor: TextAlign = "left",
  ): void {
    if (!Number.isInteger(size) || size < 1 || size > 4) {
      throw new Error("Text scale must be an integer from 1 through 4.");
    }
    if (!Number.isInteger(atX) || !Number.isInteger(atY)) {
      throw new Error("Text coordinates must be integers.");
    }
    if (anchor !== "left" && anchor !== "center" && anchor !== "right") {
      throw new Error("Invalid text alignment.");
    }

    const srcRows = typeof copy === "string" ? [copy] : copy;
    const rows = srcRows.flatMap((row) => normalizeText(row).split("\n"));

    for (let li = 0; li < rows.length; li++) {
      const row = rows[li];
      const wide = row.length * CELL_WIDTH * size;
      const x0 = anchor === "center"
        ? atX - wide / 2
        : anchor === "right"
        ? atX - wide
        : atX;
      const y0 = atY + li * LINE_HEIGHT * size;

      const box: Rect = {
        x: x0,
        y: y0,
        width: wide,
        height: CELL_HEIGHT * size,
      };

      assertContentRect(box, `Text "${row}"`);

      if (this.textAreas.some((earlier) => rectanglesOverlap(box, earlier))) {
        throw new Error(`Text overlaps an earlier line: "${row}".`);
      }
      this.textAreas.push(box);

      for (let ci = 0; ci < row.length; ci++) {
        const code = row.charCodeAt(ci);
        const glyphBase = (code - 32) * GLYPH_BYTES;
        const gx = x0 + ci * CELL_WIDTH * size;

        for (let r = 0; r < CELL_HEIGHT; r++) {
          for (let col = 0; col < CELL_WIDTH; col++) {
            const byteAt =
              glyphBase + r * (CELL_WIDTH / 8) + (col >>> 3);
            const bit = 0x80 >>> (col & 7);

            if ((this.font[byteAt] & bit) !== 0) {
              this.fillRect(
                gx + col * size,
                y0 + r * size,
                size,
                size,
                paint,
              );
            }
          }
        }
      }
    }
  }

  // Scale the ghost bitmap onto the canvas with bilinear resampling.
  drawGhost(
    img: DecodedImage,
    atX: number,
    atY: number,
    side: number,
  ): void {
    if (
      !Number.isInteger(atX) ||
      !Number.isInteger(atY) ||
      !Number.isInteger(side) ||
      side <= 0
    ) {
      throw new Error("Ghost placement requires integer coordinates and size.");
    }

    assertContentRect({ x: atX, y: atY, width: side, height: side }, "Ghost");

    for (let dy = 0; dy < side; dy++) {
      const srcY = ((dy + 0.5) * img.height) / side - 0.5;
      const by = Math.floor(srcY);
      const fracY = srcY - by;

      for (let dx = 0; dx < side; dx++) {
        const srcX = ((dx + 0.5) * img.width) / side - 0.5;
        const bx = Math.floor(srcX);
        const fracX = srcX - bx;

        let a = 0;
        let pmR = 0;
        let pmG = 0;
        let pmB = 0;

        // Interpolate premultiplied samples to prevent transparent-edge
        // color fringes, then use standard source-over compositing.
        for (let sy2 = 0; sy2 < 2; sy2++) {
          const sy = Math.max(0, Math.min(img.height - 1, by + sy2));
          const wy = sy2 === 0 ? 1 - fracY : fracY;

          for (let sx2 = 0; sx2 < 2; sx2++) {
            const sx = Math.max(0, Math.min(img.width - 1, bx + sx2));
            const wx = sx2 === 0 ? 1 - fracX : fracX;
            const w = wx * wy;
            const off = (sy * img.width + sx) * 4;
            const wA = img.pixels[off + 3] * w;

            a += wA;
            pmR += img.pixels[off] * wA;
            pmG += img.pixels[off + 1] * wA;
            pmB += img.pixels[off + 2] * wA;
          }
        }

        if (a > 0) {
          this.blendPixel(
            atX + dx,
            atY + dy,
            pmR / a,
            pmG / a,
            pmB / a,
            a,
          );
        }
      }
    }
  }
}

// A section title: scale 2 when it fits the content width, otherwise
// scale 1 so it never clips. Alignment is the caller's choice.
function drawTitle(
  sheet: Canvas,
  text: string,
  x: number,
  y: number,
  color: Color,
  align: TextAlign,
): void {
  const ascii = normalizeText(text);
  const size = ascii.length * CELL_WIDTH * 2 <= CONTENT_WIDTH ? 2 : 1;
  sheet.drawText(ascii, x, y, size, color, align);
}

// A big two-line headline: each input line is wrapped to what fits at
// scale 2 across the content width, then drawn at scale 2.
function drawHeadline(
  sheet: Canvas,
  headlines: readonly string[],
  x: number,
  y: number,
  color: Color,
  align: TextAlign,
): void {
  const perLine = Math.floor(CONTENT_WIDTH / (CELL_WIDTH * 2));
  const broken = headlines.flatMap((headline) => wrapText(headline, perLine));
  sheet.drawText(broken, x, y, 2, color, align);
}

// A left-aligned ledger: each entry wrapped to what fits at scale 1
// across the content width, stacked with the given spacing.
function drawRows(
  sheet: Canvas,
  entries: readonly string[],
  firstY: number,
  spacing: number,
  color: Color,
): void {
  const perLine = Math.floor(CONTENT_WIDTH / CELL_WIDTH);
  for (let index = 0; index < entries.length; index += 1) {
    sheet.drawText(
      wrapText(entries[index], perLine),
      MARGIN,
      firstY + index * spacing,
      1,
      color,
      "left",
    );
  }
}

