function drawChat(font: Uint8Array, ghost: DecodedImage): Canvas {
  // Chat palette: pale background, dark ink, white and green bubbles.
  const chatBack: Color = [246, 248, 247, 255];
  const pineInk: Color = [24, 43, 36, 255];
  const softGrey: Color = [88, 109, 99, 255];
  const bubbleWhite: Color = [255, 255, 255, 255];
  const bubbleEdge: Color = [187, 200, 193, 255];
  const replyGreen: Color = [211, 239, 220, 255];
  const replyEdge: Color = [139, 178, 151, 255];
  const avatarTeal: Color = [22, 68, 65, 255];
  const shadeBlack: Color = [15, 29, 27, 255];
  const routeGold: Color = [225, 181, 85, 255];
  const dialCream: Color = [255, 251, 235, 255];
  const deepTeal: Color = [0, 90, 77, 255];

  // Per-glyph ink span [left, right] inside the 24 px cell, codes 32-126.
  // A span of [0,-1] marks a blank glyph (space, underscore).
  const GLYPH_SPANS: ReadonlyArray<readonly [number, number]> = [
    [0,-1], [4,6], [3,9], [2,16], [2,13], // codes 32-36
    [2,19], [2,16], [3,4], [3,7], [3,7], // codes 37-41
    [2,10], [3,15], [3,6], [2,7], [3,6], // codes 42-46
    [1,7], [2,13], [3,13], [2,12], [2,12], // codes 47-51
    [2,13], [2,13], [2,13], [2,12], [2,13], // codes 52-56
    [2,13], [3,6], [3,6], [3,15], [3,15], // codes 57-61
    [3,15], [2,10], [2,19], [1,15], [3,14], // codes 62-66
    [2,14], [3,16], [3,12], [3,12], [2,15], // codes 67-71
    [3,15], [3,6], [3,6], [3,16], [3,12], // codes 72-76
    [3,18], [3,15], [2,16], [3,14], [2,16], // codes 77-81
    [3,15], [2,13], [1,14], [3,15], [1,15], // codes 82-86
    [2,21], [2,15], [1,14], [2,14], [3,8], // codes 87-91
    [1,7], [2,8], [3,14], [0,-1], [2,6], // codes 92-96
    [2,12], [3,14], [2,11], [2,13], [2,13], // codes 97-101
    [1,9], [2,13], [3,13], [3,5], [3,5], // codes 102-106
    [3,13], [3,5], [3,19], [3,13], [2,13], // codes 107-111
    [3,14], [2,13], [3,10], [2,11], [1,9], // codes 112-116
    [2,13], [1,13], [2,18], [2,12], [1,13], // codes 117-121
    [2,11], [3,12], [3,5], [3,12], [3,15], // codes 122-126
  ];

  // One glyph cell is 24 px wide, 20 px tall, stored as 3 bytes per row.
  const cellW = 24;
  const cellH = 20;
  const rowBytes = 3;
  const glyphSize = cellH * rowBytes;
  const sheet = new Canvas(font, chatBack);

  // Rounded rectangle: two bars plus four corner discs.
  function roundBox(
    left: number,
    top: number,
    wide: number,
    tall: number,
    corner: number,
    paint: Color,
  ): void {
    const r = Math.min(corner, wide / 2, tall / 2);

    sheet.fillRect(left + r, top, wide - r * 2, tall, paint);
    sheet.fillRect(left, top + r, wide, tall - r * 2, paint);
    sheet.filledCircle(left + r, top + r, r, paint);
    sheet.filledCircle(left + wide - r, top + r, r, paint);
    sheet.filledCircle(left + r, top + tall - r, r, paint);
    sheet.filledCircle(left + wide - r, top + tall - r, r, paint);
  }

  // Thick line as a rotated quad with round caps (float offsets, no rounding).
  function roundStroke(
    fromX: number,
    fromY: number,
    toX: number,
    toY: number,
    thick: number,
    paint: Color,
  ): void {
    const cap = thick / 2;
    const span = Math.hypot(toX - fromX, toY - fromY);

    if (span === 0) {
      sheet.filledCircle(fromX, fromY, cap, paint);
      return;
    }

    const offX = ((toY - fromY) / span) * cap;
    const offY = ((toX - fromX) / span) * cap;

    sheet.fillPolygon(
      [
        [fromX - offX, fromY + offY],
        [toX - offX, toY + offY],
        [toX + offX, toY - offY],
        [fromX + offX, fromY - offY],
      ],
      paint,
    );
    sheet.filledCircle(fromX, fromY, cap, paint);
    sheet.filledCircle(toX, toY, cap, paint);
  }

  // Speech bubble: rounded body plus a triangular tail on one side.
  function chatBubble(
    atX: number,
    atY: number,
    wide: number,
    tall: number,
    face: Color,
    frame: Color,
    side: "left" | "right",
    tailLen: number = 16,
  ): void {
    const dir = side === "left" ? -1 : 1;
    const lip = side === "left" ? atX : atX + wide;
    const midY = atY + Math.floor(tall / 2);

    roundBox(atX, atY, wide, tall, 26, frame);
    sheet.fillPolygon(
      [
        [lip - dir * 12, midY - 17],
        [lip + dir * tailLen, midY],
        [lip - dir * 12, midY + 19],
      ],
      frame,
    );

    roundBox(atX + 2, atY + 2, wide - 4, tall - 4, 24, face);
    sheet.fillPolygon(
      [
        [lip - dir * 12, midY - 14],
        [lip + dir * (tailLen - 4), midY],
        [lip - dir * 12, midY + 16],
      ],
      face,
    );
  }

  function spanFor(code: number): readonly [number, number] {
    const span = GLYPH_SPANS[code - 32];
    if (span === undefined) {
      throw new Error(`Unsupported chat glyph with character code ${code}.`);
    }
    return span;
  }

  function advanceFor(lo: number, hi: number): number {
    return hi < lo ? 8 : hi - lo + 1 + 2;
  }

  // Total pixel width of a line at a given scale.
  function measureLabel(copy: string, size: number): number {
    let total = 0;
    for (let k = 0; k < copy.length; k += 1) {
      const [lo, hi] = spanFor(copy.charCodeAt(k));
      total += advanceFor(lo, hi) * size;
    }
    return total;
  }

  // Paint one line of proportional text; the anchor picks its left edge.
  function paintText(
    copy: string,
    atX: number,
    atY: number,
    size: number,
    paint: Color,
    anchor: "left" | "center" | "right",
  ): void {
    const totalW = measureLabel(copy, size);
    const originX = anchor === "center"
      ? atX - totalW / 2
      : anchor === "right"
      ? atX - totalW
      : atX;

    if (!Number.isInteger(originX)) {
      throw new Error(`Chat line "${copy}" starts between pixels.`);
    }

    assertContentRect(
      { x: originX, y: atY, width: totalW, height: cellH * size },
      `Text "${copy}"`,
    );

    let cursorX = originX;
    for (let k = 0; k < copy.length; k += 1) {
      const code = copy.charCodeAt(k);
      const [lo, hi] = spanFor(code);
      const step = advanceFor(lo, hi) * size;

      if (hi >= lo) {
        const glyphBase = (code - 32) * glyphSize;
        const drawX = cursorX + size - lo * size;

        for (let row = 0; row < cellH; row += 1) {
          for (let col = 0; col < cellW; col += 1) {
            const byteAt = glyphBase + row * rowBytes + (col >>> 3);
            const bit = 0x80 >>> (col & 7);

            if ((font[byteAt] & bit) !== 0) {
              sheet.fillRect(
                drawX + col * size,
                atY + row * size,
                size,
                size,
                paint,
              );
            }
          }
        }
      }

      cursorX += step;
    }
  }

  // Multi-line message inside a bubble: fixed scale 2, fixed 52 px line step.
  function paintMessage(
    rows: readonly string[],
    atX: number,
    atY: number,
    wide: number,
    tall: number,
    rowInks: readonly Color[],
    padTop: number,
    rowGap: number,
  ): void {
    const size = 2;
    const padX = 32;
    const innerW = wide - padX * 2;
    const blockH = cellH * size + (rows.length - 1) * rowGap;

    if (
      rows.length === 0 ||
      padTop < 0 ||
      rowGap !== 52 ||
      padTop + blockH > tall
    ) {
      throw new Error("Chat message does not fit its bubble vertically.");
    }

    for (const row of rows) {
      const rowW = measureLabel(row, size);
      if (rowW > innerW) {
        throw new Error(
          `Chat line "${row}" requires ${rowW}px but has ${innerW}px.`,
        );
      }
    }

    rows.forEach((row, k) => {
      paintText(
        row,
        atX + padX,
        atY + padTop + k * rowGap,
        size,
        rowInks[k] ?? pineInk,
        "left",
      );
    });
  }

  paintText("MY AGENT", 512, 80, 2, pineInk, "center");

  chatBubble(468, 176, 476, 136, replyGreen, replyEdge, "right");
  paintMessage(
    ["Still waiting", "for GTA VI."],
    468, 176, 476, 136,
    [pineInk, pineInk],
    22, 52,
  );

  chatBubble(296, 344, 560, 192, bubbleWhite, bubbleEdge, "left", 24);
  paintMessage(
    ["GTA VI fund: full.", "Won a bounty on", "make.fun."],
    296, 344, 560, 192,
    [pineInk, pineInk, deepTeal],
    24, 52,
  );

  paintText("3 DAYS LATER", 576, 598, 1, softGrey, "center");

  chatBubble(296, 652, 560, 140, bubbleWhite, bubbleEdge, "left");
  paintMessage(
    ["You make Rockstar", "look punctual."],
    296, 652, 560, 140,
    [pineInk, pineInk],
    24, 52,
  );

  // The agent's avatar: teal disc, ghost, glasses, and a gold watch.
  const ghostLeft = 80;
  const ghostTop = 344;
  const ghostSide = 192;

  sheet.filledCircle(176, 440, 96, avatarTeal);
  sheet.drawGhost(ghost, ghostLeft, ghostTop, ghostSide);

  // Preserve contact where the tail and circle meet at a single point.
  sheet.fillRect(272, 440, 1, 1, bubbleEdge);

  const eyeLeftX = Math.round(ghostLeft + (51 / 144) * ghostSide);
  const eyeRightX = Math.round(ghostLeft + (93 / 144) * ghostSide);
  const whiteY = Math.round(ghostTop + (45 / 144) * ghostSide);
  const dotY = Math.round(ghostTop + (42 / 144) * ghostSide);
  const frameY = dotY + 7;

  roundBox(eyeLeftX - 24, frameY, 48, 29, 7, shadeBlack);
  roundBox(eyeRightX - 24, frameY, 48, 29, 7, shadeBlack);
  sheet.horizontalLine(
    eyeLeftX - 29,
    frameY + 5,
    eyeRightX - eyeLeftX + 58,
    shadeBlack,
    4,
  );

  sheet.filledCircle(eyeLeftX, whiteY, 13, bubbleWhite);
  sheet.filledCircle(eyeRightX, whiteY, 13, bubbleWhite);
  sheet.filledCircle(eyeLeftX, dotY, 8, shadeBlack);
  sheet.filledCircle(eyeRightX, dotY, 8, shadeBlack);

  roundBox(237, 451, 18, 84, 6, routeGold);
  sheet.filledCircle(246, 493, 32, routeGold);

  // The rounded fingertip reaches the upper-left rim.
  roundStroke(169, 452, 222, 470, 18, pineInk);
  roundStroke(169, 452, 222, 470, 14, bubbleWhite);

  sheet.filledCircle(246, 493, 24, dialCream);
  roundStroke(246, 493, 233, 485, 6, pineInk);
  roundStroke(246, 493, 263, 483, 6, pineInk);
  sheet.filledCircle(246, 493, 3, pineInk);

  paintText("YOU | STILL TYPING", 944, 832, 2, softGrey, "right");

  chatBubble(768, 888, 176, 56, replyGreen, replyEdge, "right");
  sheet.filledCircle(812, 916, 11, softGrey);
  sheet.filledCircle(856, 916, 11, softGrey);
  sheet.filledCircle(900, 916, 11, softGrey);

  return sheet;
}

function drawHinge(font: Uint8Array, ghost: DecodedImage): Canvas {
  // One glyph cell is 24 px wide, 20 px tall, stored as 3 bytes per row.
  const cellW = 24;
  const cellH = 20;
  const rowBytes = 3;
  const glyphSize = cellH * rowBytes;
  const tealDeep: Color = [13, 74, 69, 255];
  const sheet = new Canvas(font, tealDeep);

  // SPDX-License-Identifier: MIT
  const labelCream: Color = [255, 248, 220, 255];
  const pineInk: Color = [24, 43, 36, 255];
  const paper: Color = [255, 255, 255, 255];
  const softTeal: Color = [120, 180, 172, 255];
  const doorIndigo: Color = [38, 52, 120, 255];
  const deepIndigo: Color = [24, 34, 84, 255];
  const brightIndigo: Color = [70, 88, 165, 255];
  const edgeBlue: Color = [130, 150, 215, 255];
  const routeGold: Color = [225, 181, 85, 255];
  const deepGold: Color = [175, 125, 48, 255];
  const skinTone: Color = [232, 190, 150, 255];

  // Rounded rectangle: two bars plus four corner discs.
  function roundBox(
    left: number,
    top: number,
    wide: number,
    tall: number,
    corner: number,
    paint: Color,
  ): void {
    const r = Math.min(corner, wide / 2, tall / 2);

    sheet.fillRect(left + r, top, wide - r * 2, tall, paint);
    sheet.fillRect(left, top + r, wide, tall - r * 2, paint);
    sheet.filledCircle(left + r, top + r, r, paint);
    sheet.filledCircle(left + wide - r, top + r, r, paint);
    sheet.filledCircle(left + r, top + tall - r, r, paint);
    sheet.filledCircle(left + wide - r, top + tall - r, r, paint);
  }

  // Thick line as a rotated quad with round caps (float offsets, no rounding).
  function roundStroke(
    fromX: number,
    fromY: number,
    toX: number,
    toY: number,
    thick: number,
    paint: Color,
  ): void {
    const cap = thick / 2;
    const span = Math.hypot(toX - fromX, toY - fromY);

    if (span === 0) {
      sheet.filledCircle(fromX, fromY, cap, paint);
      return;
    }

    const offX = ((toY - fromY) / span) * cap;
    const offY = ((toX - fromX) / span) * cap;

    sheet.fillPolygon(
      [
        [fromX - offX, fromY + offY],
        [toX - offX, toY + offY],
        [toX + offX, toY - offY],
        [fromX + offX, fromY - offY],
      ],
      paint,
    );
    sheet.filledCircle(fromX, fromY, cap, paint);
    sheet.filledCircle(toX, toY, cap, paint);
  }

  // Per-glyph ink span [left, right] inside the 24 px cell, codes 32-126.
  // A span of [0,-1] marks a blank glyph (space, underscore).
  const GLYPH_SPANS: ReadonlyArray<readonly [number, number]> = [
    [0,-1], [4,6], [3,9], [2,16], [2,13], // codes 32-36
    [2,19], [2,16], [3,4], [3,7], [3,7], // codes 37-41
    [2,10], [3,15], [3,6], [2,7], [3,6], // codes 42-46
    [1,7], [2,13], [3,13], [2,12], [2,12], // codes 47-51
    [2,13], [2,13], [2,13], [2,12], [2,13], // codes 52-56
    [2,13], [3,6], [3,6], [3,15], [3,15], // codes 57-61
    [3,15], [2,10], [2,19], [1,15], [3,14], // codes 62-66
    [2,14], [3,16], [3,12], [3,12], [2,15], // codes 67-71
    [3,15], [3,6], [3,6], [3,16], [3,12], // codes 72-76
    [3,18], [3,15], [2,16], [3,14], [2,16], // codes 77-81
    [3,15], [2,13], [1,14], [3,15], [1,15], // codes 82-86
    [2,21], [2,15], [1,14], [2,14], [3,8], // codes 87-91
    [1,7], [2,8], [3,14], [0,-1], [2,6], // codes 92-96
    [2,12], [3,14], [2,11], [2,13], [2,13], // codes 97-101
    [1,9], [2,13], [3,13], [3,5], [3,5], // codes 102-106
    [3,13], [3,5], [3,19], [3,13], [2,13], // codes 107-111
    [3,14], [2,13], [3,10], [2,11], [1,9], // codes 112-116
    [2,13], [1,13], [2,18], [2,12], [1,13], // codes 117-121
    [2,11], [3,12], [3,5], [3,12], [3,15], // codes 122-126
  ];

  function spanFor(code: number): readonly [number, number] {
    const span = GLYPH_SPANS[code - 32];
    if (span === undefined) {
      throw new Error(`Unsupported chat glyph with character code ${code}.`);
    }
    return span;
  }

  function advanceFor(lo: number, hi: number): number {
    return hi < lo ? 8 : hi - lo + 1 + 2;
  }

  // Total pixel width of a line at a given scale.
  function measureLabel(copy: string, size: number): number {
    let total = 0;
    for (let k = 0; k < copy.length; k += 1) {
      const [lo, hi] = spanFor(copy.charCodeAt(k));
      total += advanceFor(lo, hi) * size;
    }
    return total;
  }

  // Paint one line of proportional text; the anchor picks its left edge.
  function paintText(
    copy: string,
    atX: number,
    atY: number,
    size: number,
    paint: Color,
    anchor: "left" | "center" | "right",
  ): void {
    const totalW = measureLabel(copy, size);
    const originX = anchor === "center"
      ? atX - totalW / 2
      : anchor === "right"
      ? atX - totalW
      : atX;

    if (!Number.isInteger(originX)) {
      throw new Error(`Chat line "${copy}" starts between pixels.`);
    }

    assertContentRect(
      { x: originX, y: atY, width: totalW, height: cellH * size },
      `Text "${copy}"`,
    );

    let cursorX = originX;
    for (let k = 0; k < copy.length; k += 1) {
      const code = copy.charCodeAt(k);
      const [lo, hi] = spanFor(code);
      const step = advanceFor(lo, hi) * size;

      if (hi >= lo) {
        const glyphBase = (code - 32) * glyphSize;
        const drawX = cursorX + size - lo * size;

        for (let row = 0; row < cellH; row += 1) {
          for (let col = 0; col < cellW; col += 1) {
            const byteAt = glyphBase + row * rowBytes + (col >>> 3);
            const bit = 0x80 >>> (col & 7);

            if ((font[byteAt] & bit) !== 0) {
              sheet.fillRect(
                drawX + col * size,
                atY + row * size,
                size,
                size,
                paint,
              );
            }
          }
        }
      }

      cursorX += step;
    }
  }

  // Speech lines for the top bubble, each checked against its padded width.
  const speech = [
    { copy: "GTA VI", atY: 84 },
    { copy: "EARLY ACCESS.", atY: 140 },
    { copy: "YOU GET THE HINGE.", atY: 196 },
  ].map((row) => {
    const size = 2;
    if (measureLabel(row.copy, size) > 472) {
      throw new Error(`Speech line "${row.copy}" exceeds its padded bubble.`);
    }
    return { copy: row.copy, atY: row.atY, size };
  });

  // The single insert line on the right leaf, checked against its box.
  const inserts = [
    { copy: "GTA VI", atX: 212, atY: 636, size: 3 },
  ].map((row) => {
    const size = row.size;
    const wide = measureLabel(row.copy, size);
    if (wide > 289 || row.atY + cellH * size > 700) {
      throw new Error(`Insert line "${row.copy}" exceeds its allotted box.`);
    }

    return {
      copy: row.copy,
      atX: row.atX,
      atY: row.atY,
      size,
    };
  });

  // Both panels share the fold beneath the continuous amber spine.
  const leftLeafBack: [number, number][] = [
    [124, 523],
    [498, 473],
    [566, 857],
    [175, 937],
  ];
  const rightLeafBack: [number, number][] = [
    [532, 470],
    [918, 454],
    [941, 871],
    [532, 860],
  ];
  const leftLeafFace: [number, number][] = [
    [131, 529],
    [493, 480],
    [559, 852],
    [180, 929],
  ];
  const rightLeafFace: [number, number][] = [
    [538, 476],
    [912, 461],
    [934, 864],
    [538, 854],
  ];
  sheet.fillPolygon(leftLeafBack, deepIndigo);
  sheet.fillPolygon(rightLeafBack, deepIndigo);
  sheet.fillPolygon(leftLeafFace, doorIndigo);
  sheet.fillPolygon(rightLeafFace, doorIndigo);

  // One bent arm connects the ghost to the right leaf.
  roundStroke(798, 416, 826, 444, 30, pineInk);
  roundStroke(826, 444, 848, 470, 30, pineInk);
  roundStroke(848, 470, 852, 480, 30, pineInk);
  roundStroke(798, 416, 826, 444, 22, paper);
  roundStroke(826, 444, 848, 470, 22, paper);
  roundStroke(848, 470, 852, 480, 22, paper);
  roundBox(828, 466, 44, 36, 12, pineInk);
  roundBox(832, 470, 36, 28, 8, paper);
  sheet.drawGhost(ghost, 590, 130, 300);

  const trayFace: [number, number][] = [
    [158, 635],
    [474, 579],
    [495, 697],
    [179, 753],
  ];
  sheet.fillPolygon(trayFace, labelCream);

  // Four separated retaining clips leave the panel-colored tray visibly empty.
  sheet.filledCircle(731, 665, 128, doorIndigo);
  for (let seg = 0; seg < 4; seg += 1) {
    const fromDeg = 15 + seg * 90;
    const toDeg = fromDeg + 60;
    const arcPts: [number, number][] = [];
    const divs = 20;

    for (let k = 0; k <= divs; k += 1) {
      const ang =
        ((fromDeg + (toDeg - fromDeg) * k / divs) *
          Math.PI) / 180;
      arcPts.push([
        Math.round(731 + Math.cos(ang) * 129),
        Math.round(665 + Math.sin(ang) * 129),
      ]);
    }

    for (let k = divs; k >= 0; k -= 1) {
      const ang =
        ((fromDeg + (toDeg - fromDeg) * k / divs) *
          Math.PI) / 180;
      arcPts.push([
        Math.round(731 + Math.cos(ang) * 117),
        Math.round(665 + Math.sin(ang) * 117),
      ]);
    }

    sheet.fillPolygon(arcPts, edgeBlue);
  }

  // Retaining-clip spokes and the hub.
  roundStroke(731, 628, 731, 606, 5, edgeBlue);
  roundStroke(763, 684, 783, 695, 5, edgeBlue);
  roundStroke(699, 684, 679, 695, 5, edgeBlue);
  sheet.filledCircle(731, 665, 14, deepIndigo);
  sheet.filledCircle(731, 665, 7, [16, 22, 56, 255]);
  sheet.filledCircle(726, 660, 3, edgeBlue);

  // The amber spine down the fold, with three dark hinges.
  roundBox(500, 464, 64, 402, 12, deepIndigo);
  roundBox(506, 470, 52, 390, 10, routeGold);
  roundBox(514, 520, 36, 22, 6, deepGold);
  roundBox(514, 650, 36, 22, 6, deepGold);
  roundBox(514, 780, 36, 22, 6, deepGold);
  roundStroke(126, 612, 110, 636, 5, routeGold);
  roundStroke(130, 672, 114, 696, 5, routeGold);

  // The viewer holds the opposite leaf, with the forearm entering from below.
  const forearmOuter: [number, number][] = [
    [232, 923],
    [198, 1000],
    [150, 1024],
    [264, 1024],
    [294, 965],
  ];
  const forearmInner: [number, number][] = [
    [236, 925],
    [202, 1002],
    [155, 1024],
    [260, 1024],
    [290, 965],
  ];
  const cuff: [number, number][] = [
    [150, 1024],
    [260, 1024],
    [250, 980],
    [170, 980],
  ];
  sheet.fillPolygon(forearmOuter, pineInk);
  sheet.fillPolygon(forearmInner, skinTone);
  sheet.fillPolygon(cuff, pineInk);

  // The viewer's hand gripping the leaf edge.
  roundBox(232, 881, 76, 60, 18, pineInk);
  roundBox(236, 885, 68, 52, 14, skinTone);
  roundStroke(250, 903, 300, 887, 30, pineInk);
  roundStroke(250, 903, 300, 887, 24, skinTone);
  roundBox(240, 933, 66, 30, 13, pineInk);
  roundBox(244, 937, 58, 22, 9, skinTone);
  roundStroke(262, 943, 262, 955, 3, pineInk);

  // Speech-bubble tail and body.
  const bubbleTail: [number, number][] = [
    [540, 200],
    [556, 184],
    [584, 280],
  ];
  sheet.fillPolygon(bubbleTail, labelCream);
  roundBox(48, 48, 520, 220, 24, labelCream);

  const brandW = measureLabel("make.fun", 2);
  roundBox(76, 292, brandW + 28, 72, 14, labelCream);

  for (const row of speech) {
    paintText(row.copy, 80, row.atY, row.size, pineInk, "left");
  }
  paintText("make.fun", 88, 304, 2, pineInk, "left");
  paintText("$500 MEME BOUNTY", 88, 384, 2, labelCream, "left");

  for (const row of inserts) {
    paintText(row.copy, row.atX, row.atY, row.size, pineInk, "left");
  }

  return sheet;
}

function drawMinimap(font: Uint8Array, ghost: DecodedImage): Canvas {
  // Palette for the Leonida minimap: deep sea, island, amber route, green shortcut.
  const abyss: Color = [10, 42, 52, 255];
  const rimTeal: Color = [23, 83, 98, 255];
  const lagoon: Color = [16, 68, 92, 255];
  const islandGreen: Color = [46, 110, 88, 255];
  const routeGold: Color = [225, 181, 85, 255];
  const shortcutMint: Color = [86, 214, 141, 255];
  const labelCream: Color = [255, 248, 220, 255];
  const paper: Color = [255, 255, 255, 255];
  const plaqueInk: Color = [12, 30, 38, 255];

  // Per-glyph ink span [left, right] inside the 24 px cell, codes 32-126.
  // A span of [0,-1] marks a blank glyph (space, underscore).
  const GLYPH_SPANS: ReadonlyArray<readonly [number, number]> = [
    [0,-1], [4,6], [3,9], [2,16], [2,13], // codes 32-36
    [2,19], [2,16], [3,4], [3,7], [3,7], // codes 37-41
    [2,10], [3,15], [3,6], [2,7], [3,6], // codes 42-46
    [1,7], [2,13], [3,13], [2,12], [2,12], // codes 47-51
    [2,13], [2,13], [2,13], [2,12], [2,13], // codes 52-56
    [2,13], [3,6], [3,6], [3,15], [3,15], // codes 57-61
    [3,15], [2,10], [2,19], [1,15], [3,14], // codes 62-66
    [2,14], [3,16], [3,12], [3,12], [2,15], // codes 67-71
    [3,15], [3,6], [3,6], [3,16], [3,12], // codes 72-76
    [3,18], [3,15], [2,16], [3,14], [2,16], // codes 77-81
    [3,15], [2,13], [1,14], [3,15], [1,15], // codes 82-86
    [2,21], [2,15], [1,14], [2,14], [3,8], // codes 87-91
    [1,7], [2,8], [3,14], [0,-1], [2,6], // codes 92-96
    [2,12], [3,14], [2,11], [2,13], [2,13], // codes 97-101
    [1,9], [2,13], [3,13], [3,5], [3,5], // codes 102-106
    [3,13], [3,5], [3,19], [3,13], [2,13], // codes 107-111
    [3,14], [2,13], [3,10], [2,11], [1,9], // codes 112-116
    [2,13], [1,13], [2,18], [2,12], [1,13], // codes 117-121
    [2,11], [3,12], [3,5], [3,12], [3,15], // codes 122-126
  ];

  // One glyph cell is 24 px wide, 20 px tall, stored as 3 bytes per row.
  const cellW = 24;
  const cellH = 20;
  const rowBytes = 3;
  const glyphSize = cellH * rowBytes;
  const sheet = new Canvas(font, abyss);

  // Rounded rectangle: two bars plus four corner discs.
  function roundBox(
    left: number,
    top: number,
    wide: number,
    tall: number,
    corner: number,
    ink: Color,
  ): void {
    const r = Math.min(corner, wide / 2, tall / 2);

    sheet.fillRect(left + r, top, wide - r * 2, tall, ink);
    sheet.fillRect(left, top + r, wide, tall - r * 2, ink);
    sheet.filledCircle(left + r, top + r, r, ink);
    sheet.filledCircle(left + wide - r, top + r, r, ink);
    sheet.filledCircle(left + r, top + tall - r, r, ink);
    sheet.filledCircle(left + wide - r, top + tall - r, r, ink);
  }

  // Thick line as a rotated quad with round caps.
  function roundStroke(
    fromX: number,
    fromY: number,
    toX: number,
    toY: number,
    thick: number,
    ink: Color,
  ): void {
    const cap = thick / 2;
    const span = Math.hypot(toX - fromX, toY - fromY);

    if (span === 0) {
      sheet.filledCircle(fromX, fromY, cap, ink);
      return;
    }

    const offX = Math.round(((toY - fromY) / span) * cap);
    const offY = Math.round(((toX - fromX) / span) * cap);

    sheet.fillPolygon(
      [
        [fromX - offX, fromY + offY],
        [toX - offX, toY + offY],
        [toX + offX, toY - offY],
        [fromX + offX, fromY - offY],
      ],
      ink,
    );
    sheet.filledCircle(fromX, fromY, cap, ink);
    sheet.filledCircle(toX, toY, cap, ink);
  }

  function spanFor(code: number): readonly [number, number] {
    const span = GLYPH_SPANS[code - 32];
    if (span === undefined) {
      throw new Error(`Unsupported chat glyph with character code ${code}.`);
    }
    return span;
  }

  function advanceFor(lo: number, hi: number): number {
    return hi < lo ? 8 : hi - lo + 1 + 2;
  }

  // Total pixel width of a line at a given scale.
  function measureLabel(copy: string, size: number): number {
    let total = 0;
    for (let k = 0; k < copy.length; k += 1) {
      const [lo, hi] = spanFor(copy.charCodeAt(k));
      total += advanceFor(lo, hi) * size;
    }
    return total;
  }

  // Paint one line of proportional text; the anchor picks its left edge.
  function paintText(
    copy: string,
    atX: number,
    atY: number,
    size: number,
    ink: Color,
    anchor: "left" | "center" | "right",
  ): void {
    const totalW = measureLabel(copy, size);
    const originX = anchor === "center"
      ? atX - totalW / 2
      : anchor === "right"
      ? atX - totalW
      : atX;

    if (!Number.isInteger(originX)) {
      throw new Error(`Chat line "${copy}" starts between pixels.`);
    }

    assertContentRect(
      { x: originX, y: atY, width: totalW, height: cellH * size },
      `Text "${copy}"`,
    );

    let cursorX = originX;
    for (let k = 0; k < copy.length; k += 1) {
      const code = copy.charCodeAt(k);
      const [lo, hi] = spanFor(code);
      const step = advanceFor(lo, hi) * size;

      if (hi >= lo) {
        const glyphBase = (code - 32) * glyphSize;
        const drawX = cursorX + size - lo * size;

        for (let row = 0; row < cellH; row += 1) {
          for (let col = 0; col < cellW; col += 1) {
            const byteAt = glyphBase + row * rowBytes + (col >>> 3);
            const bit = 0x80 >>> (col & 7);

            if ((font[byteAt] & bit) !== 0) {
              sheet.fillRect(
                drawX + col * size,
                atY + row * size,
                size,
                size,
                ink,
              );
            }
          }
        }
      }

      cursorX += step;
    }
  }

  // Dashed connector: short round-capped runs with a dark outline underneath.
  function dashStroke(
    fromX: number,
    fromY: number,
    toX: number,
    toY: number,
    thick: number,
    ink: Color,
  ): void {
    const runX = toX - fromX;
    const runY = toY - fromY;
    const span = Math.hypot(runX, runY);
    const dashLen = 34;
    const gapLen = 18;
    const cap = thick / 2;

    // Inset each segment by its cap radius to preserve the visible gap.
    for (let off = 0; off + thick <= span; off += dashLen + gapLen) {
      const begin = (off + cap) / span;
      const finish = (Math.min(off + dashLen, span) - cap) / span;
      const ax = Math.round(fromX + runX * begin);
      const ay = Math.round(fromY + runY * begin);
      const bx = Math.round(fromX + runX * finish);
      const by = Math.round(fromY + runY * finish);

      roundStroke(ax, ay, bx, by, thick + 6, plaqueInk);
      roundStroke(ax, ay, bx, by, thick, ink);
    }
  }

  type Pt = [number, number];

  // Polyline through a list of points.
  function tracePath(
    stops: readonly Pt[],
    thick: number,
    ink: Color,
  ): void {
    for (let k = 1; k < stops.length; k += 1) {
      const [ax, ay] = stops[k - 1];
      const [bx, by] = stops[k];
      roundStroke(ax, ay, bx, by, thick, ink);
    }
  }

  // Anchor points shared by the route, the shortcut, and the plaque.
  const fork: Pt = [470, 800];
  const markerFoot: Pt = [395, 755];
  const plaquePoint: Pt = [310, 575];
  const brandName = "make.fun";
  const brandSize = 3;
  const brandLeft = 279;
  const brandTop = 415;
  const plaqueLeft = 183;
  const plaqueTop = 404;
  const plaqueW =
    Math.max(measureLabel(brandName, brandSize), measureLabel("$500 MEME BOUNTY", 2)) + (brandLeft - plaqueLeft) + 16;
  const plaqueH = 140;

  // Every caption on the map, in draw order.
  const captions = [
    {
      copy: "ETA: 13 YEARS",
      atX: 465,
      atY: 140,
      size: 3,
      ink: routeGold,
      anchor: "center",
    },
    {
      copy: "GTA VI",
      atX: 680,
      atY: 690,
      size: 3,
      ink: labelCream,
      anchor: "left",
    },
    {
      copy: brandName,
      atX: brandLeft,
      atY: brandTop,
      size: brandSize,
      ink: labelCream,
      anchor: "left",
    },
    {
      copy: "$500 MEME BOUNTY",
      atX: 279,
      atY: 490,
      size: 2,
      ink: labelCream,
      anchor: "left",
    },
    {
      copy: "YOU",
      atX: 400,
      atY: 855,
      size: 4,
      ink: paper,
      anchor: "center",
    },
  ] as const;

  const captionBoxes = captions.map(({ copy, atX, atY, size, ink, anchor }) => {
    const wide = measureLabel(copy, size);

    // Odd-width centered text needs a half-pixel adjustment before rendering.
    // Snap its left edge while preserving the integer-only paintText helper.
    const left = Math.round(anchor === "center" ? atX - wide / 2 : atX);

    return {
      copy,
      size,
      ink,
      left,
      right: left + wide,
      top: atY,
      bottom: atY + cellH * size,
    };
  });

  // Every caption must sit inside the canvas and clear every other caption.
  for (let k = 0; k < captionBoxes.length; k += 1) {
    const first = captionBoxes[k];

    assertContentRect(
      {
        x: first.left,
        y: first.top,
        width: first.right - first.left,
        height: first.bottom - first.top,
      },
      `Text "${first.copy}"`,
    );

    for (let m = k + 1; m < captionBoxes.length; m += 1) {
      const second = captionBoxes[m];
      if (
        first.left < second.right &&
        second.left < first.right &&
        first.top < second.bottom &&
        second.top < first.bottom
      ) {
        throw new Error(`Minimap labels "${first.copy}" and "${second.copy}" overlap.`);
      }
    }
  }

  function paintLabel(k: number): void {
    const { copy, left, top, size, ink } = captionBoxes[k];
    paintText(copy, left, top, size, ink, "left");
  }

  // Ghost slots must stay inside the canvas.
  assertContentRect(
    { x: 195, y: 414, width: 72, height: 72 },
    "Plaque ghost",
  );
  assertContentRect(
    { x: 88, y: 690, width: 210, height: 210 },
    "Big ghost",
  );

  // The map disc: rim, sea, then the Leonida landmass.
  const mapCX = 465;
  const mapCY = 540;
  const rimR = 382;
  const seaR = 376;
  sheet.filledCircle(mapCX, mapCY, rimR, rimTeal);
  sheet.filledCircle(mapCX, mapCY, seaR, lagoon);
  const coastline: Pt[] = [
    [142, 370],
    [214, 305],
    [286, 288],
    [336, 311],
    [411, 259],
    [487, 223],
    [577, 243],
    [671, 310],
    [741, 417],
    [785, 494],
    [781, 548],
    [809, 607],
    [783, 674],
    [747, 707],
    [709, 781],
    [645, 832],
    [594, 835],
    [547, 795],
    [519, 756],
    [451, 730],
    [398, 666],
    [323, 630],
    [264, 630],
    [224, 571],
    [161, 556],
    [127, 499],
    [146, 441],
    [117, 411],
  ];
  sheet.fillPolygon(coastline, islandGreen);

  // The absurd amber loop: starts at the fork, circles the whole island.
  const loopRoute: Pt[] = [
    fork,
    [330, 790], // south-west bend
    [220, 720], // west approach
    [150, 610], // west shore
    [135, 490], // far west
    [175, 375], // north-west
    [270, 285], // north-west bay
    [400, 235], // north shore
    [550, 230], // north point
    [660, 265], // north-east
    [745, 335], // east shore
    [790, 450], // far east
    [770, 570], // south-east
    [720, 660], // south-east bend
    [640, 620], // inland kink
    [610, 715], // south approach
    [560, 720], // destination
  ];

  tracePath(loopRoute, 22, plaqueInk);
  tracePath(loopRoute, 14, routeGold);
  // Arrowhead at the top of the loop, dark outline then amber fill.
  const loopArrowOuter: Pt[] = [[504, 232], [464, 212], [465, 254]];
  const loopArrowInner: Pt[] = [[500, 232], [468, 215], [469, 251]];
  // Down-pointing marker above the destination star.
  const destMarker: Pt[] = [[560, 694], [542, 726], [578, 726]];
  sheet.fillPolygon(loopArrowOuter, plaqueInk);
  sheet.fillPolygon(loopArrowInner, routeGold);
  sheet.fillPolygon(destMarker, routeGold);

  sheet.filledCircle(560, 720, 26, plaqueInk);

  // Ten-point star at the destination, alternating long and short spikes.
  const starPts: Pt[] = [];
  for (let k = 0; k < 10; k += 1) {
    const ang = -Math.PI / 2 + k * Math.PI / 5;
    const spike = k % 2 === 0 ? 21 : 9;
    starPts.push([
      Math.round(560 + Math.cos(ang) * spike),
      Math.round(720 + Math.sin(ang) * spike),
    ]);
  }
  sheet.fillPolygon(starPts, routeGold);

  // Connect the amber fork to the same branch beneath the YOU marker.
  dashStroke(...fork, ...markerFoot, 14, shortcutMint);
  dashStroke(...plaquePoint, ...markerFoot, 14, shortcutMint);
  sheet.filledCircle(...fork, 14, plaqueInk);
  sheet.filledCircle(...fork, 9, shortcutMint);

  // The make.fun plaque: green frame, dark face, pointer tip below.
  roundBox(
    plaqueLeft,
    plaqueTop,
    plaqueW,
    plaqueH,
    22,
    shortcutMint,
  );
  roundBox(
    plaqueLeft + 4,
    plaqueTop + 4,
    plaqueW - 8,
    plaqueH - 8,
    18,
    plaqueInk,
  );
  const plaqueTipOuter: Pt[] = [[292, 544], [328, 544], [310, 574]];
  const plaqueTipInner: Pt[] = [[296, 544], [324, 544], [310, 568]];
  sheet.fillPolygon(plaqueTipOuter, shortcutMint);
  sheet.fillPolygon(plaqueTipInner, plaqueInk);
  sheet.drawGhost(ghost, 195, 414, 72);
  paintLabel(2);
  paintLabel(3);

  // The ghost's arm reaching from the lower left toward the marker.
  const reach: Pt[] = [
    [285, 805], // wrist
    [330, 790], // forearm
    [365, 775], // elbow
    [395, 762], // hand
  ];
  tracePath(reach, 38, plaqueInk);
  tracePath(reach, 26, paper);
  sheet.drawGhost(ghost, 88, 690, 210);

  // Open hand pulling the YOU marker out of the loop.
  const palmOuter: Pt[] = [[341, 711], [455, 757], [428, 782], [410, 812]];
  const palmInner: Pt[] = [[351, 721], [445, 757], [418, 780], [400, 808]];
  sheet.fillPolygon(palmOuter, plaqueInk);
  sheet.fillPolygon(palmInner, paper);

  const fingerSegs: [number, number, number, number][] = [
    [400, 752, 420, 762], // index finger
    [402, 770, 422, 774], // middle finger
    [400, 788, 419, 786], // ring finger
  ];
  for (const [ax, ay, bx, by] of fingerSegs) {
    roundStroke(ax, ay, bx, by, 14, plaqueInk);
    roundStroke(ax, ay, bx, by, 8, paper);
  }

  paintLabel(0);
  paintLabel(1);
  paintLabel(4);

  return sheet;
}

// Command-line options: --variant 1-6 (default 6, the minimap winner),
// --outdir <directory>, --help / -h. Unknown flags and missing values
// are hard errors with a short message.
function parseArguments(argv: readonly string[]): Options {
  let variant: Variant = 6;
  let outdir: string | undefined;
  let help = false;

  function parseVariant(value: string): Variant {
    if (!["1", "2", "3", "4", "5", "6"].includes(value)) {
      throw new Error("--variant must be 1, 2, 3, 4, 5, or 6.");
    }
    return Number(value) as Variant;
  }

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === "--help" || token === "-h") {
      help = true;
    } else if (token === "--variant") {
      const value = argv[++index];
      if (value === undefined) {
        throw new Error("--variant requires a value.");
      }
      variant = parseVariant(value);
    } else if (token.startsWith("--variant=")) {
      variant = parseVariant(token.slice("--variant=".length));
    } else if (token === "--outdir") {
      const value = argv[++index];
      if (value === undefined || value.length === 0 || value.startsWith("--")) {
        throw new Error("--outdir requires a directory.");
      }
      outdir = value;
    } else if (token.startsWith("--outdir=")) {
      const value = token.slice("--outdir=".length);
      if (value.length === 0) {
        throw new Error("--outdir requires a directory.");
      }
      outdir = value;
    } else {
      throw new Error(`Unknown argument: ${token}`);
    }
  }

  return { variant, outdir, help };
}

// Resolve a directory, create it (and parents) if needed, and confirm it
// is really a writable directory before anything is written into it.
function ensureDirectory(target: string): string {
  const absolute = path.resolve(target);
  fs.mkdirSync(absolute, { recursive: true });

  if (!fs.statSync(absolute).isDirectory()) {
    throw new Error(`Output path is not a directory: ${absolute}`);
  }

  fs.accessSync(absolute, fs.constants.W_OK);
  return absolute;
}

// Output priority, in order: the --outdir flag, MAKEFUN_OUTPUT_DIR,
// the /output directory, and finally an "out" folder beside main.ts.
// The first one that can be created and written wins.
function selectOutputDirectory(flag: string | undefined): string {
  if (flag !== undefined) {
    return ensureDirectory(flag);
  }

  const fromEnv = process.env.MAKEFUN_OUTPUT_DIR;
  if (fromEnv !== undefined && fromEnv.length > 0) {
    return ensureDirectory(fromEnv);
  }

  try {
    return ensureDirectory("/output");
  } catch {
    return ensureDirectory(path.join(SCRIPT_DIR, "out"));
  }
}

// POST.json sits beside main.ts and is copied alongside the PNG when the
// meme has been posted. Missing file is fine (not posted yet); any other
// read failure is a real error.
function readOptionalPost(): Buffer | undefined {
  try {
    return fs.readFileSync(path.join(SCRIPT_DIR, "POST.json"));
  } catch (error) {
    if (
      error !== null &&
      typeof error === "object" &&
      "code" in error &&
      error.code === "ENOENT"
    ) {
      return undefined;
    }
    throw error;
  }
}

// Write a file into the output directory, refusing to follow a symlink
// so a fixed output filename cannot be redirected outside the directory.
// The file is created with mode 0644.
function writeOutputFile(
  directory: string,
  name: "meme.png" | "POST.json",
  data: Uint8Array,
): void {
  const target = path.join(directory, name);

  // Refuse a pre-existing symlink so a fixed output filename cannot redirect
  // writes to a file outside the chosen directory.
  try {
    const current = fs.lstatSync(target);
    if (!current.isFile() || current.isSymbolicLink()) {
      throw new Error(`Output destination must be a regular file: ${target}`);
    }
  } catch (error) {
    if (
      error === null ||
      typeof error !== "object" ||
      !("code" in error) ||
      error.code !== "ENOENT"
    ) {
      throw error;
    }
  }

  const noFollowFlag = fs.constants.O_NOFOLLOW ?? 0;
  const handle = fs.openSync(
    target,
    fs.constants.O_WRONLY |
      fs.constants.O_CREAT |
      fs.constants.O_TRUNC |
      noFollowFlag,
    0o644,
  );

  try {
    fs.writeFileSync(handle, data);
  } finally {
    fs.closeSync(handle);
  }
}

// Entry point: parse options, decode the font and ghost, draw the chosen
// variant, encode it as PNG, and write meme.png (plus POST.json when it
// exists) into the selected output directory.
function main(): void {
  const opts = parseArguments(process.argv.slice(2));

  if (opts.help) {
    process.stdout.write(
      "Usage: node main.ts [--variant 1|2|3|4|5] [--outdir <directory>]\n" +
      "Output priority: --outdir, MAKEFUN_OUTPUT_DIR, /output, ./out beside main.ts.\n",
    );
    return;
  }

  const font = decodeFont();
  const ghost = decodeGhost();

  let artwork: Canvas;
  switch (opts.variant) {
    case 1:
      artwork = drawVariant1(font, ghost);
      break;
    case 2:
      artwork = drawVariant2(font, ghost);
      break;
    case 3:
      artwork = drawVariant3(font, ghost);
      break;
    case 4:
      artwork = drawChat(font, ghost);
      break;
    case 5:
      artwork = drawHinge(font, ghost);
      break;
    case 6:
      artwork = drawMinimap(font, ghost);
      break;
  }

  const image = encodePNG(artwork.pixels);
  const postBytes = readOptionalPost();
  const directory = selectOutputDirectory(opts.outdir);

  writeOutputFile(directory, "meme.png", image);
  if (postBytes !== undefined) {
    writeOutputFile(directory, "POST.json", postBytes);
  }
}

try {
  main();
} catch (error) {
  const message = error instanceof Error ? error.message : String(error);
  process.stderr.write(`main.ts: ${message}\n`);
  process.exitCode = 1;
}